1	import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
2	import type { SyntheticEvent } from 'react';
3	import { useIsMutating, useQueryClient } from '@tanstack/react-query';
4	import type { ShopperBasketsV2Types, ShopperProductsTypes } from 'commerce-sdk-isomorphic';
5	import {
6	  useCustomerId,
7	  useCustomerType,
8	  useProducts,
9	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
10	  useShopperCustomersMutation,
11	} from '@salesforce/commerce-sdk-react';
12	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
13	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
14	import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
15	import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
16	
17	import ProductItem from 'app/components/product-item';
18	import { ZimmCartDrawer } from 'app/components/ui-kits/organisms/zimmCartDrawer';
19	import { ZimmCartEmptyState } from 'app/components/ui-kits/organisms/zimmCartEmptyState';
20	import { ZimmCartButtonGroup } from 'app/components/ui-kits/molecules/zimmCartButtonGroup';
21	import { ZimmCartItemActions } from 'app/components/ui-kits/molecules/zimmCartItemActions';
22	import type { WishlistMoveResult } from 'app/components/ui-kits/molecules/zimmCartItemActions/usePendingWishlistItem';
23	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
24	import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
25	import { breakpoints } from 'app/theme/foundation';
26	import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
27	import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
28	import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
29	import type { UseWishlistAuthDrawerReturn } from 'app/hooks/useWishlistAuthDrawer';
30	import { useCartMergeAndCap } from 'app/hooks/useCartMergeAndCap';
31	import { useCartMessages } from 'app/hooks/useCartMessages';
32	import { selectCartItemProps } from './cartItemMapper';
33	
34	/*
35	 * SFCC-11 plan step 4.6 — "the real assembly." This is the file `ZimmCartDrawer` (SFCC-315),
36	 * `cartItemMapper` (SFCC-271/250), `useCartMergeAndCap` (SFCC-250), `useCartMessages` (SFCC-272),
37	 * `ZimmCartItemActions` (SFCC-272), `ZimmCartEmptyState` (SFCC-272/277) and `ZimmCartButtonGroup`
38	 * (SFCC-275) were all built anticipating but never wired to — see each of those files' own
39	 * docblocks, which all point here. Owns `useCurrentBasket()` (and every other commerce-SDK hook
40	 * this container needs) deliberately: `.claude/rules/components.md`'s container/presentational
41	 * rule forbids that under `overrides/app/components/`, which is why this lives under
42	 * `overrides/app/pages/cart/` instead (a sibling file, not `index.tsx` — base `pages/cart/
43	 * index.jsx` still serves `/cart` untouched, per this plan's own resolved open question 8).
44	 *
45	 * Deliberately out of scope (disclosed, not silently dropped):
46	 * - `onItemQuantityChange` is not wired to a real basket mutation. No pass criterion, Changes
47	 *   item, or Tester check for this step names it, and no other step in the plan claims it either
48	 *   — `ProductItem`'s own default (`async () => true`) applies, so the quantity stepper updates
49	 *   only local, optimistic state this commit. A shopper's quantity edit in the cart drawer does
50	 *   not yet persist server-side. Flagged in this step's own report as a real, material gap for a
51	 *   later step to claim, not something invented here.
52	 * - Per-line "isRemoving" loading-spinner feedback (base `pages/cart/index.jsx`'s own
53	 *   `removingItemIds` state) is not reproduced — no pass criterion asks for it, and `ProductItem`
54	 *   already has its own `showLoading` prop for exactly this if a future step wants it.
55	 */
56	
57	type SfccBasket = ShopperBasketsV2Types.Basket;
58	type SfccBasketProductItem = ShopperBasketsV2Types.BasketProductItem;
59	
60	// `useCurrentBasket` is a base, untyped (`.js`) hook — AGENTS.md's "Commerce SDK types not
61	// importable" gotcha, same pattern cartItemMapper.ts/useCartMergeAndCap.ts already use for the
62	// identical gap. `ShopperBasketsV2Types.Basket` (not the V1 `ShopperBasketsTypes.Basket`
63	// cartItemMapper.ts's own `CartLineItem` type references) is used here to match
64	// useCartMergeAndCap's own `CartCapBasket` — the two SDK namespaces' generated `Basket`/
65	// `ProductItem`/`BasketProductItem` shapes are field-for-field identical (verified directly
66	// against commerce-sdk-isomorphic's own generated .d.ts, both fully-optional plus the same
67	// `{[key: string]: any}` catch-all), so a value typed against one satisfies the other
68	// structurally — no second, parallel type is needed for the cartItemMapper.selectCartItemProps
69	// call below.
70	type UseCurrentBasketReturn = {
71	  data: SfccBasket | undefined;
72	  isLoading: boolean;
73	};
74	
75	const CART_WISHLIST_INTENT_ID = 'cart-wishlist';
76	
77	// The API does not respect this value — it always adds 1 regardless of what is sent (confirmed,
78	// overrides/app/pages/product-detail/index.tsx's own identical comment against the same
79	// createCustomerProductListItem call). Sent explicitly anyway, as a named constant rather than an
80	// inline `1`, per conventions.md's "no magic numbers" rule.
81	const WISHLIST_ADD_QUANTITY = 1;
82	
83	export type CartDrawerContainerProps = {
84	  /** Whether the drawer is open. Owned by whichever component mounts this container (the
85	   *  drawer-open lifecycle, per step 9's own `useCartDrawer()` provider) — this container never
86	   *  reads or owns that state itself (pass criterion 7). */
87	  isOpen: boolean;
88	  /** Called on backdrop click, Escape, and the close button — forwarded to `ZimmCartDrawer`
89	   *  verbatim, not wrapped. */
90	  onClose: () => void;
91	  /** Forwarded to `ZimmCartDrawer`'s own `finalFocusRef` (AC10 focus-return for the cart drawer
92	   *  itself) — see this container's own `openGuestWishlistDrawer` for the separate, disclosed
93	   *  focus-return story for the nested wishlist auth drawer. */
94	  finalFocusRef?: React.RefObject<HTMLElement>;
95	};
96	
97	/**
98	 * Presentational sub-tree for the one shared wishlist auth gate — split out of the main component
99	 * body purely for readability (components.md's ~150-line guideline); still the same one file, no
100	 * new component/props contract for anything outside this module to depend on. Mirrors
101	 * `ZimmWishlistAuthDrawer`'s own render body (`app/components/ui-kits/organisms/
102	 * zimmWishlistAuthDrawer/index.tsx`) minus the single-trigger `cloneElement` wrapping, which does
103	 * not apply here — see this file's own `openGuestWishlistDrawer` for why a many-rows container
104	 * cannot use that component as-is. Duplicating this specific composition (rather than extracting
105	 * a shared piece out of `zimmWishlistAuthDrawer/index.tsx`) is a disclosed, deliberate tradeoff:
106	 * that file is outside this step's manifest, and its `children: React.ReactElement` contract is
107	 * structurally single-trigger, so there is no lower-risk shared extraction point available from
108	 * this step's own scope.
109	 */
110	const CartWishlistAuthGate = ({ wishlistAuthDrawer }: { wishlistAuthDrawer: UseWishlistAuthDrawerReturn }) => {
111	  // SFCC-926 (Figma), mirrored from zimmWishlistAuthDrawer/index.tsx: mobile full-width (`large`,
112	  // which is itself responsive down to mobile — see zimmDrawer.css.ts), desktop (>= xl) `small`.
113	  // That file also tracks an `isTabletOrAbove` value that is computed but never actually read by
114	  // its own final `drawerSize` ternary (checked directly against its current code, not assumed) —
115	  // not reproduced here since duplicating unused state would just be a second copy of the same
116	  // gap, not a faithful port of real behaviour.
117	  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
118	  useEffect(() => {
119	    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
120	    setIsDesktopOrAbove(desktopMq.matches);
121	    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
122	    desktopMq.addEventListener('change', onDesktop);
123	    return () => desktopMq.removeEventListener('change', onDesktop);
124	  }, []);
125	  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';
126	
127	  return (
128	    <>
129	      <ZimmDrawer
130	        isOpen={wishlistAuthDrawer.isOpen}
131	        onClose={wishlistAuthDrawer.handleDrawerClose}
132	        size={drawerSize}
133	        title={wishlistAuthDrawer.drawerTitle}
134	        finalFocusRef={wishlistAuthDrawer.triggerRef}
135	        initialFocusRef={wishlistAuthDrawer.emailInputRef}
136	      >
137	        <ErrorFallback>
138	          <ZimmAuthDrawerContent
139	            description={wishlistAuthDrawer.description}
140	            emailValue={wishlistAuthDrawer.emailValue}
141	            onEmailChange={wishlistAuthDrawer.onEmailChange}
142	            onSendCode={wishlistAuthDrawer.onSendCode}
143	            onSignInWithApple={wishlistAuthDrawer.onSignInWithApple}
144	            onSignInWithGoogle={wishlistAuthDrawer.onSignInWithGoogle}
145	            onCreateAccount={wishlistAuthDrawer.onCreateAccount}
146	            socialEnabled={wishlistAuthDrawer.isSocialEnabled}
147	            passwordlessEnabled={wishlistAuthDrawer.isPasswordlessEnabled}
148	            initialFocusRef={wishlistAuthDrawer.emailInputRef}
149	          />
150	        </ErrorFallback>
151	      </ZimmDrawer>
152	      <AuthModal {...wishlistAuthDrawer.registerModal} />
153	      <OtpAuth
154	        isOpen={wishlistAuthDrawer.isOtpAuthOpen}
155	        onClose={wishlistAuthDrawer.onOtpAuthClose}
156	        form={wishlistAuthDrawer.form}
157	        handleSendEmailOtp={wishlistAuthDrawer.handlePasswordlessLogin}
158	        handleOtpVerification={wishlistAuthDrawer.handleOtpVerification}
159	        hideCheckoutAsGuestButton={true}
160	      />
161	    </>
162	  );
163	};
164	
165	/**
166	 * Container — the real cart-drawer content assembly (SFCC-11 plan step 4.6). See this file's own
167	 * module docblock for why this owns `useCurrentBasket()` and lives under `pages/cart/`, not
168	 * `components/`.
169	 */
170	export const CartDrawerContainer = ({ isOpen, onClose, finalFocusRef }: CartDrawerContainerProps) => {
171	  const { data: basket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
172	  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
173	  const itemCount = productItems.length;
174	
175	  // Base `pages/cart/index.jsx`'s own real precedent for building ProductItem's `product` prop
176	  // (`{...productItem, ...productsByItemId[productItem.itemId], price: productItem.price,
177	  // quantity: ...}`, node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) — minus
178	  // `allImages: true` on the fetch (over-fetching, and the exact parameter implicated in the
179	  // SFCC-29 outage) and minus its bundle/bonus-product/multi-location-inventory enrichment (real
180	  // complexity this epic never asked for). One correction against that same base file, found by
181	  // reading it in full rather than trusting a paraphrase: its OWN per-line lookup map
182	  // (`productsByItemId`, a second, separate useMemo) is keyed by `productItem.itemId`, but is
183	  // itself built from `products?.[productItem?.productId]` — i.e. the raw `useProducts` fetch
184	  // below is keyed by PRODUCT id, not item id, and the re-keying-by-itemId step exists there only
185	  // to support the bundle-child-inventory enrichment this container does not replicate. This
186	  // container looks the fetched product up by `productId` directly, with no intermediate re-keyed
187	  // map.
188	  // The generated `getProducts` query parameters type this SDK call resolves against
189	  // (`getProductsQueryParameters`, commerce-sdk-isomorphic) types `ids` as `Array<string>` — base
190	  // `pages/cart/index.jsx`'s own equivalent call passes a comma-joined string instead (its own
191	  // file is untyped `.jsx`, so nothing catches the mismatch there); an array is what this
192	  // TypeScript call site actually needs.
193	  const productIds = productItems.map((item) => item.productId).filter((id): id is string => Boolean(id));
194	  const { data: productsResult, isLoading: isProductsLoading } = useProducts(
195	    { parameters: { ids: productIds, perPricebook: true } },
196	    { enabled: productIds.length > 0 },
197	  );
198	  // Reshaped outside the hook call, not via a `select` option: commerce-sdk-react's own
199	  // `ApiQueryOptions` type pins `select`'s return type to the query's own raw result type
200	  // (`UseQueryOptions<DataType<Method>, unknown, DataType<Method>, ...>` — the third, `TData`,
201	  // generic is hard-coded to match the first), so a `select` reshaping into a keyed map does not
202	  // type-check here even though base's own untyped `.jsx` equivalent does exactly this via its
203	  // own `select`. A `useMemo` outside the hook achieves the identical keyed-by-product-id shape.
204	  const productsById = useMemo(
205	    () =>
206	      (productsResult?.data ?? []).reduce((acc: Record<string, ShopperProductsTypes.Product>, product) => {
207	        acc[product.id] = product;
208	        return acc;
209	      }, {} as Record<string, ShopperProductsTypes.Product>),
210	    [productsResult],
211	  );
212	
213	  /* -------------------------------------------------------------------------------------------
214	   * Pass criterion 2 — useCartMergeAndCap's render guard, this hook's second of two call sites
215	   * (the first, the post-auth callback, was wired into useWishlistAuthDrawer.ts back in step 4.2).
216	   * Keyed on `[basket]` (react-query returns a stable reference across renders where the basket
217	   * data hasn't actually changed, thanks to structural sharing) rather than on
218	   * `capBasketQuantities` itself, which useCartMergeAndCap does not memoise — a fresh function
219	   * reference every render, so including it here would re-run this effect on every render instead
220	   * of only on a real basket-state change. capBasketQuantities' own internal guards (mutation-in-
221	   * flight, already-attempted-this-version) would make an extra call harmless regardless, but
222	   * "runs on a basket-driven re-render" is this criterion's own explicit framing.
223	   * ---------------------------------------------------------------------------------------- */
224	  const { capBasketQuantities } = useCartMergeAndCap();
225	  const { notifyMaxQuantityReached } = useCartMessages();
226	  // notifyAddedToWishlist/notifyAlreadyInWishlist are NOT called from this container — verified
227	  // directly against zimmCartItemActions/index.tsx's own current code (not assumed from this
228	  // step's own plan text, which describes all three as called "by this container"): ZimmCartItemActions
229	  // already calls useCartMessages itself and fires both from its own attemptMoveToWishlist. Calling
230	  // them again here would double-fire the toast for a single successful move. notifyMaxQuantityReached
231	  // is the one function with no other call site anywhere in this codebase — genuinely this
232	  // container's own responsibility, fired below once the render guard reports a real correction.
233	  useEffect(() => {
234	    if (!basket?.basketId) return;
235	    void capBasketQuantities(basket).then((result) => {
236	      if (result.status === 'corrected') {
237	        notifyMaxQuantityReached();
238	      }
239	    });
240	  }, [basket]);
241	
242	  /* -------------------------------------------------------------------------------------------
243	   * Pass criterion 4 — the wishlist-move resume must wait for the merge-then-cap chain to settle.
244	   * See useWishlistAuthDrawer.ts's own isRegistered effect: onAuthSuccess fires synchronously,
245	   * immediately before mergeBasket.mutate(...) — so isGuest cannot simply mirror `!isRegistered`
246	   * one-for-one, or ZimmCartItemActions' resumed usePendingWishlistItem effect (keyed on
247	   * `[isGuest]`) could fire before the merge has even started.
248	   *
249	   * hasPendingPostAuthSettleRef is a ref, not React state, deliberately: useWishlistAuthDrawer()
250	   * is called (below) before this gating effect is declared, so within the SAME commit, its own
251	   * internal [isRegistered] effect runs first and calls handleAuthSuccess synchronously — a
252	   * setState there would only become visible on a LATER render (one render behind), which would
253	   * let this effect's very first run (in the same commit as the isRegistered flip) read a stale
254	   * "not yet settling" value and flip isGuestState to false immediately, before mergeBasket.mutate
255	   * has registered anything in the mutation cache. A ref mutation is visible immediately to any
256	   * code running later in the same synchronous effect-flush pass, which is exactly what this
257	   * needs. This is the same class of stale-closure trap useCartMergeAndCap.ts's own docblock
258	   * already documents fixing (a React-render-time value instead of a live read) — applied here to
259	   * the ordering between two different hooks in the same fiber rather than to a single async
260	   * closure.
261	   *
262	   * queryClient.isMutating() (a live, imperative read, taken fresh at the moment this effect body
263	   * runs) — not the reactive `isMutatingSignal` value below — is what actually decides whether to
264	   * flip isGuestState. `isMutatingSignal` (useIsMutating()) exists purely so this effect re-runs
265	   * every time the app-wide mutation count changes, giving it a fresh chance to re-check the live
266	   * value; using its own render-time value directly would reintroduce the identical stale-read
267	   * risk described above. Matches useCartMergeAndCap.ts's own documented reasoning for the same
268	   * hook pairing (queryClient.isMutating() for correctness, useIsMutating() for reactivity).
269	   * ---------------------------------------------------------------------------------------- */
270	  const { isRegistered } = useCustomerType();
271	  const [isGuestState, setIsGuestState] = useState(!isRegistered);
272	  const queryClient = useQueryClient();
273	  const isMutatingSignal = useIsMutating();
274	  const hasPendingPostAuthSettleRef = useRef(false);
275	
276	  const handleAuthSuccess = useCallback(() => {
277	    hasPendingPostAuthSettleRef.current = true;
278	  }, []);
279	
280	  const wishlistAuthDrawer = useWishlistAuthDrawer({
281	    onAuthSuccess: handleAuthSuccess,
282	    intentId: CART_WISHLIST_INTENT_ID,
283	  });
284	
285	  useEffect(() => {
286	    if (!isRegistered) {
287	      setIsGuestState(true);
288	      return;
289	    }
290	    // Steady-state (a shopper already registered when this container mounts) never sets the ref,
291	    // so `!hasPendingPostAuthSettleRef.current` is true immediately — no artificial wait for
292	    // someone with nothing to wait for.
293	    if (!hasPendingPostAuthSettleRef.current || queryClient.isMutating() === 0) {
294	      hasPendingPostAuthSettleRef.current = false;
295	      setIsGuestState(false);
296	    }
297	  }, [isRegistered, isMutatingSignal, queryClient]);
298	
299	  /**
300	   * Opens the one shared wishlist auth drawer from any row's guest click. ZimmCartItemActions'
301	   * onGuestWishlistClick is `() => void` — no event to forward, because every row shares this one
302	   * drawer instance (ZimmCartItemActions' own docblock explicitly rejects one useWishlistAuthDrawer
303	   * per row). useWishlistAuthDrawer's handleTriggerClick needs a SyntheticEvent purely to capture
304	   * `e.currentTarget` as the AC10 focus-return target.
305	   *
306	   * document.activeElement is deliberately NOT used as a substitute here, even though it could
307	   * plausibly hold the real clicked row's own link at this exact point in the call stack:
308	   * useWishlistAuthDrawer.ts's own handleTriggerClick comment already documents exactly why it
309	   * chose `e.currentTarget` over `document.activeElement` for this identical purpose — "unlike
310	   * document.activeElement which may still be body on click." Building this on a mechanism that
311	   * file's own author already rejected for the same job would trade one honest degradation for a
312	   * silently unreliable one.
313	   *
314	   * Corrected 2026-09-21 (step 4.6's own Tester, live-rendered rather than assumed): an earlier
315	   * version of this comment claimed the fallback lands on `document.body`, citing ZimmCartDrawer's
316	   * own doc for that behaviour. That doc describes what Chakra does with no `finalFocusRef` at
317	   * all — not what actually happens here, where `document.body` IS passed as `currentTarget`.
318	   * Live-rendering the real close sequence instead, focus actually lands on the still-open outer
319	   * cart drawer's own `aria-hidden` initial-focus sentinel (ZimmDrawer's own focus-management
320	   * internals) — a real, disclosed, named degradation, just a different actual mechanism than
321	   * previously claimed here: a keyboard user ends up parked on an invisible, unannounced element
322	   * rather than on `document.body`. Worth a follow-up ticket on the real UX gap; not fixed in this
323	   * step, which only owns getting this comment's own factual claim right. AC10 remains fully
324	   * correct for every genuine single-trigger caller (header/PDP wishlist icon), which still goes
325	   * through the unmodified <ZimmWishlistAuthDrawer/> wrapper, not this container.
326	   */
327	  const openGuestWishlistDrawer = useCallback(() => {
328	    wishlistAuthDrawer.handleTriggerClick({ currentTarget: document.body } as unknown as SyntheticEvent<HTMLElement>);
329	  }, [wishlistAuthDrawer.handleTriggerClick]);
330	
331	  /* -------------------------------------------------------------------------------------------
332	   * Pass criterion 3 — real remove/wishlist-move mutations, not stubs.
333	   * ---------------------------------------------------------------------------------------- */
334	  const removeItemFromBasketMutation = useShopperBasketsMutation('removeItemFromBasket');
335	  const customerId = useCustomerId();
336	  const { data: wishlist } = useWishList();
337	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
338	
339	  const removeItem = async (itemId?: string): Promise<void> => {
340	    if (!basket?.basketId || !itemId) return;
341	    await removeItemFromBasketMutation.mutateAsync({ parameters: { basketId: basket.basketId, itemId } });
342	  };
343	
344	  const moveToWishlist = async (productId: string): Promise<WishlistMoveResult> => {
345	    // Same lookup base product-detail/index.tsx's own handleAddToWishlist uses against
346	    // wishlist?.customerProductListItems.
347	    const isAlreadyInWishlist = wishlist?.customerProductListItems?.some(
348	      (item: { productId?: string }) => item.productId === productId,
349	    );
350	    if (isAlreadyInWishlist) {
351	      return { status: 'already-in-wishlist' };
352	    }
353	    if (!wishlist?.id) {
354	      // useWishList() auto-provisions a wish_list for a first-time registered customer and only
355	      // resolves it asynchronously (see that hook's own onSuccess) — surfaced as an error rather
356	      // than silently doing nothing, matching useCartMergeAndCap.ts's own "nothing valid to
357	      // address a write at" precedent.
358	      return { status: 'error', error: new Error('cartDrawerContainer: no wishlist available yet.') };
359	    }
360	    try {
361	      await createCustomerProductListItem.mutateAsync({
362	        parameters: {
363	          listId: wishlist.id,
364	          // SDK param widening — useCustomerId returns string | null; onMoveToWishlist is only
365	          // ever invoked for a registered shopper (ZimmCartItemActions only calls this prop
366	          // directly when isGuest is false, and the resumed path only fires once isGuest has
367	          // become false — see usePendingWishlistItem.ts), matching product-detail/index.tsx's
368	          // own identical cast for the same real precondition.
369	          customerId: customerId as string,
370	        },
371	        body: {
372	          // NOTE: API does not respect quantity, it always adds 1 — see WISHLIST_ADD_QUANTITY's
373	          // own comment above.
374	          quantity: WISHLIST_ADD_QUANTITY,
375	          productId,
376	          public: false,
377	          priority: 1,
378	          type: 'product',
379	        },
380	      });
381	      return { status: 'success' };
382	    } catch (error) {
383	      return { status: 'error', error };
384	    }
385	  };
386	
387	  return (
388	    <>
389	      <ZimmCartDrawer
390	        isOpen={isOpen}
391	        onClose={onClose}
392	        itemCount={itemCount}
393	        finalFocusRef={finalFocusRef}
394	        footer={<ZimmCartButtonGroup />}
395	      >
396	        {itemCount === 0 ? (
397	          <ZimmCartEmptyState />
398	        ) : (
399	          productItems.map((item) => {
400	            const fullProduct = item.productId ? productsById?.[item.productId] : undefined;
401	            const mergedProduct = {
402	              ...item,
403	              ...fullProduct,
404	              // Re-asserted after both spreads, matching base's own precedent exactly: the fetched
405	              // catalog Product record can carry its own `price` field, which would otherwise
406	              // silently overwrite the basket-line's real, discount-aware price.
407	              price: item.price,
408	              quantity: item.quantity,
409	              isProductUnavailable: !isProductsLoading ? !fullProduct : undefined,
410	            };
411	            // Pass criterion 1 — cartItemMapper's output used verbatim: productId/name feed
412	            // ZimmCartItemActions below (as productId/productName) — not a second, hand-rolled
413	            // mapping. The full mergedProduct object, not this mapped result, is what ProductItem
414	            // itself needs (see this file's own module docblock and cartItemMapper.ts's own
415	            // docblock for why its output alone is not a complete `product` prop).
416	            const mapped = selectCartItemProps(mergedProduct);
417	            return (
418	              <ProductItem
419	                key={item.itemId}
420	                product={mergedProduct}
421	                secondaryActions={
422	                  <ZimmCartItemActions
423	                    productId={mapped.productId ?? ''}
424	                    productName={mapped.name}
425	                    isGuest={isGuestState}
426	                    onRemove={() => removeItem(item.itemId)}
427	                    onMoveToWishlist={() => moveToWishlist(mapped.productId ?? '')}
428	                    onGuestWishlistClick={openGuestWishlistDrawer}
429	                  />
430	                }
431	              />
432	            );
433	          })
434	        )}
435	      </ZimmCartDrawer>
436	      <CartWishlistAuthGate wishlistAuthDrawer={wishlistAuthDrawer} />
437	    </>
438	  );
439	};
