import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { SyntheticEvent } from 'react';
import { useIsMutating, useQueryClient } from '@tanstack/react-query';
import type { ShopperBasketsV2Types, ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import {
  useCustomerId,
  useCustomerType,
  useProducts,
  useShopperBasketsV2Mutation as useShopperBasketsMutation,
  useShopperCustomersMutation,
} from '@salesforce/commerce-sdk-react';
import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';

import ProductItem from 'app/components/product-item';
import { ZimmCartDrawer } from 'app/components/ui-kits/organisms/zimmCartDrawer';
import { ZimmCartEmptyState } from 'app/components/ui-kits/organisms/zimmCartEmptyState';
import { ZimmCartButtonGroup } from 'app/components/ui-kits/molecules/zimmCartButtonGroup';
import { ZimmCartItemActions } from 'app/components/ui-kits/molecules/zimmCartItemActions';
import type { WishlistMoveResult } from 'app/components/ui-kits/molecules/zimmCartItemActions/usePendingWishlistItem';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
import { breakpoints } from 'app/theme/foundation';
import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
import type { UseWishlistAuthDrawerReturn } from 'app/hooks/useWishlistAuthDrawer';
import { useCartMergeAndCap } from 'app/hooks/useCartMergeAndCap';
import { useCartMessages } from 'app/hooks/useCartMessages';
import { selectCartItemProps } from './cartItemMapper';

/*
 * SFCC-11 plan step 4.6 — "the real assembly." This is the file `ZimmCartDrawer` (SFCC-315),
 * `cartItemMapper` (SFCC-271/250), `useCartMergeAndCap` (SFCC-250), `useCartMessages` (SFCC-272),
 * `ZimmCartItemActions` (SFCC-272), `ZimmCartEmptyState` (SFCC-272/277) and `ZimmCartButtonGroup`
 * (SFCC-275) were all built anticipating but never wired to — see each of those files' own
 * docblocks, which all point here. Owns `useCurrentBasket()` (and every other commerce-SDK hook
 * this container needs) deliberately: `.claude/rules/components.md`'s container/presentational
 * rule forbids that under `overrides/app/components/`, which is why this lives under
 * `overrides/app/pages/cart/` instead (a sibling file, not `index.tsx` — base `pages/cart/
 * index.jsx` still serves `/cart` untouched, per this plan's own resolved open question 8).
 *
 * Deliberately out of scope (disclosed, not silently dropped):
 * - `onItemQuantityChange` is not wired to a real basket mutation. No pass criterion, Changes
 *   item, or Tester check for this step names it, and no other step in the plan claims it either
 *   — `ProductItem`'s own default (`async () => true`) applies, so the quantity stepper updates
 *   only local, optimistic state this commit. A shopper's quantity edit in the cart drawer does
 *   not yet persist server-side. Flagged in this step's own report as a real, material gap for a
 *   later step to claim, not something invented here.
 * - Per-line "isRemoving" loading-spinner feedback (base `pages/cart/index.jsx`'s own
 *   `removingItemIds` state) is not reproduced — no pass criterion asks for it, and `ProductItem`
 *   already has its own `showLoading` prop for exactly this if a future step wants it.
 */

type SfccBasket = ShopperBasketsV2Types.Basket;
type SfccBasketProductItem = ShopperBasketsV2Types.BasketProductItem;

// `useCurrentBasket` is a base, untyped (`.js`) hook — AGENTS.md's "Commerce SDK types not
// importable" gotcha, same pattern cartItemMapper.ts/useCartMergeAndCap.ts already use for the
// identical gap. `ShopperBasketsV2Types.Basket` (not the V1 `ShopperBasketsTypes.Basket`
// cartItemMapper.ts's own `CartLineItem` type references) is used here to match
// useCartMergeAndCap's own `CartCapBasket` — the two SDK namespaces' generated `Basket`/
// `ProductItem`/`BasketProductItem` shapes are field-for-field identical (verified directly
// against commerce-sdk-isomorphic's own generated .d.ts, both fully-optional plus the same
// `{[key: string]: any}` catch-all), so a value typed against one satisfies the other
// structurally — no second, parallel type is needed for the cartItemMapper.selectCartItemProps
// call below.
type UseCurrentBasketReturn = {
  data: SfccBasket | undefined;
  isLoading: boolean;
};

const CART_WISHLIST_INTENT_ID = 'cart-wishlist';

// The API does not respect this value — it always adds 1 regardless of what is sent (confirmed,
// overrides/app/pages/product-detail/index.tsx's own identical comment against the same
// createCustomerProductListItem call). Sent explicitly anyway, as a named constant rather than an
// inline `1`, per conventions.md's "no magic numbers" rule.
const WISHLIST_ADD_QUANTITY = 1;

export type CartDrawerContainerProps = {
  /** Whether the drawer is open. Owned by whichever component mounts this container (the
   *  drawer-open lifecycle, per step 9's own `useCartDrawer()` provider) — this container never
   *  reads or owns that state itself (pass criterion 7). */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button — forwarded to `ZimmCartDrawer`
   *  verbatim, not wrapped. */
  onClose: () => void;
  /** Forwarded to `ZimmCartDrawer`'s own `finalFocusRef` (AC10 focus-return for the cart drawer
   *  itself) — see this container's own `openGuestWishlistDrawer` for the separate, disclosed
   *  focus-return story for the nested wishlist auth drawer. */
  finalFocusRef?: React.RefObject<HTMLElement>;
};

/**
 * Presentational sub-tree for the one shared wishlist auth gate — split out of the main component
 * body purely for readability (components.md's ~150-line guideline); still the same one file, no
 * new component/props contract for anything outside this module to depend on. Mirrors
 * `ZimmWishlistAuthDrawer`'s own render body (`app/components/ui-kits/organisms/
 * zimmWishlistAuthDrawer/index.tsx`) minus the single-trigger `cloneElement` wrapping, which does
 * not apply here — see this file's own `openGuestWishlistDrawer` for why a many-rows container
 * cannot use that component as-is. Duplicating this specific composition (rather than extracting
 * a shared piece out of `zimmWishlistAuthDrawer/index.tsx`) is a disclosed, deliberate tradeoff:
 * that file is outside this step's manifest, and its `children: React.ReactElement` contract is
 * structurally single-trigger, so there is no lower-risk shared extraction point available from
 * this step's own scope.
 */
const CartWishlistAuthGate = ({ wishlistAuthDrawer }: { wishlistAuthDrawer: UseWishlistAuthDrawerReturn }) => {
  // SFCC-926 (Figma), mirrored from zimmWishlistAuthDrawer/index.tsx: mobile full-width (`large`,
  // which is itself responsive down to mobile — see zimmDrawer.css.ts), desktop (>= xl) `small`.
  // That file also tracks an `isTabletOrAbove` value that is computed but never actually read by
  // its own final `drawerSize` ternary (checked directly against its current code, not assumed) —
  // not reproduced here since duplicating unused state would just be a second copy of the same
  // gap, not a faithful port of real behaviour.
  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
  useEffect(() => {
    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
    setIsDesktopOrAbove(desktopMq.matches);
    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
    desktopMq.addEventListener('change', onDesktop);
    return () => desktopMq.removeEventListener('change', onDesktop);
  }, []);
  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';

  return (
    <>
      <ZimmDrawer
        isOpen={wishlistAuthDrawer.isOpen}
        onClose={wishlistAuthDrawer.handleDrawerClose}
        size={drawerSize}
        title={wishlistAuthDrawer.drawerTitle}
        finalFocusRef={wishlistAuthDrawer.triggerRef}
        initialFocusRef={wishlistAuthDrawer.emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={wishlistAuthDrawer.description}
            emailValue={wishlistAuthDrawer.emailValue}
            onEmailChange={wishlistAuthDrawer.onEmailChange}
            onSendCode={wishlistAuthDrawer.onSendCode}
            onSignInWithApple={wishlistAuthDrawer.onSignInWithApple}
            onSignInWithGoogle={wishlistAuthDrawer.onSignInWithGoogle}
            onCreateAccount={wishlistAuthDrawer.onCreateAccount}
            socialEnabled={wishlistAuthDrawer.isSocialEnabled}
            passwordlessEnabled={wishlistAuthDrawer.isPasswordlessEnabled}
            initialFocusRef={wishlistAuthDrawer.emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...wishlistAuthDrawer.registerModal} />
      <OtpAuth
        isOpen={wishlistAuthDrawer.isOtpAuthOpen}
        onClose={wishlistAuthDrawer.onOtpAuthClose}
        form={wishlistAuthDrawer.form}
        handleSendEmailOtp={wishlistAuthDrawer.handlePasswordlessLogin}
        handleOtpVerification={wishlistAuthDrawer.handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

/**
 * Container — the real cart-drawer content assembly (SFCC-11 plan step 4.6). See this file's own
 * module docblock for why this owns `useCurrentBasket()` and lives under `pages/cart/`, not
 * `components/`.
 */
export const CartDrawerContainer = ({ isOpen, onClose, finalFocusRef }: CartDrawerContainerProps) => {
  const { data: basket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
  const itemCount = productItems.length;

  // Base `pages/cart/index.jsx`'s own real precedent for building ProductItem's `product` prop
  // (`{...productItem, ...productsByItemId[productItem.itemId], price: productItem.price,
  // quantity: ...}`, node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) — minus
  // `allImages: true` on the fetch (over-fetching, and the exact parameter implicated in the
  // SFCC-29 outage) and minus its bundle/bonus-product/multi-location-inventory enrichment (real
  // complexity this epic never asked for). One correction against that same base file, found by
  // reading it in full rather than trusting a paraphrase: its OWN per-line lookup map
  // (`productsByItemId`, a second, separate useMemo) is keyed by `productItem.itemId`, but is
  // itself built from `products?.[productItem?.productId]` — i.e. the raw `useProducts` fetch
  // below is keyed by PRODUCT id, not item id, and the re-keying-by-itemId step exists there only
  // to support the bundle-child-inventory enrichment this container does not replicate. This
  // container looks the fetched product up by `productId` directly, with no intermediate re-keyed
  // map.
  // The generated `getProducts` query parameters type this SDK call resolves against
  // (`getProductsQueryParameters`, commerce-sdk-isomorphic) types `ids` as `Array<string>` — base
  // `pages/cart/index.jsx`'s own equivalent call passes a comma-joined string instead (its own
  // file is untyped `.jsx`, so nothing catches the mismatch there); an array is what this
  // TypeScript call site actually needs.
  const productIds = productItems.map((item) => item.productId).filter((id): id is string => Boolean(id));
  const { data: productsResult, isLoading: isProductsLoading } = useProducts(
    { parameters: { ids: productIds, perPricebook: true } },
    { enabled: productIds.length > 0 },
  );
  // Reshaped outside the hook call, not via a `select` option: commerce-sdk-react's own
  // `ApiQueryOptions` type pins `select`'s return type to the query's own raw result type
  // (`UseQueryOptions<DataType<Method>, unknown, DataType<Method>, ...>` — the third, `TData`,
  // generic is hard-coded to match the first), so a `select` reshaping into a keyed map does not
  // type-check here even though base's own untyped `.jsx` equivalent does exactly this via its
  // own `select`. A `useMemo` outside the hook achieves the identical keyed-by-product-id shape.
  const productsById = useMemo(
    () =>
      (productsResult?.data ?? []).reduce((acc: Record<string, ShopperProductsTypes.Product>, product) => {
        acc[product.id] = product;
        return acc;
      }, {} as Record<string, ShopperProductsTypes.Product>),
    [productsResult],
  );

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 2 — useCartMergeAndCap's render guard, this hook's second of two call sites
   * (the first, the post-auth callback, was wired into useWishlistAuthDrawer.ts back in step 4.2).
   * Keyed on `[basket]` (react-query returns a stable reference across renders where the basket
   * data hasn't actually changed, thanks to structural sharing) rather than on
   * `capBasketQuantities` itself, which useCartMergeAndCap does not memoise — a fresh function
   * reference every render, so including it here would re-run this effect on every render instead
   * of only on a real basket-state change. capBasketQuantities' own internal guards (mutation-in-
   * flight, already-attempted-this-version) would make an extra call harmless regardless, but
   * "runs on a basket-driven re-render" is this criterion's own explicit framing.
   * ---------------------------------------------------------------------------------------- */
  const { capBasketQuantities } = useCartMergeAndCap();
  const { notifyMaxQuantityReached } = useCartMessages();
  // notifyAddedToWishlist/notifyAlreadyInWishlist are NOT called from this container — verified
  // directly against zimmCartItemActions/index.tsx's own current code (not assumed from this
  // step's own plan text, which describes all three as called "by this container"): ZimmCartItemActions
  // already calls useCartMessages itself and fires both from its own attemptMoveToWishlist. Calling
  // them again here would double-fire the toast for a single successful move. notifyMaxQuantityReached
  // is the one function with no other call site anywhere in this codebase — genuinely this
  // container's own responsibility, fired below once the render guard reports a real correction.
  useEffect(() => {
    if (!basket?.basketId) return;
    void capBasketQuantities(basket).then((result) => {
      if (result.status === 'corrected') {
        notifyMaxQuantityReached();
      }
    });
  }, [basket]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 4 — the wishlist-move resume must wait for the merge-then-cap chain to settle.
   * See useWishlistAuthDrawer.ts's own isRegistered effect: onAuthSuccess fires synchronously,
   * immediately before mergeBasket.mutate(...) — so isGuest cannot simply mirror `!isRegistered`
   * one-for-one, or ZimmCartItemActions' resumed usePendingWishlistItem effect (keyed on
   * `[isGuest]`) could fire before the merge has even started.
   *
   * hasPendingPostAuthSettleRef is a ref, not React state, deliberately: useWishlistAuthDrawer()
   * is called (below) before this gating effect is declared, so within the SAME commit, its own
   * internal [isRegistered] effect runs first and calls handleAuthSuccess synchronously — a
   * setState there would only become visible on a LATER render (one render behind), which would
   * let this effect's very first run (in the same commit as the isRegistered flip) read a stale
   * "not yet settling" value and flip isGuestState to false immediately, before mergeBasket.mutate
   * has registered anything in the mutation cache. A ref mutation is visible immediately to any
   * code running later in the same synchronous effect-flush pass, which is exactly what this
   * needs. This is the same class of stale-closure trap useCartMergeAndCap.ts's own docblock
   * already documents fixing (a React-render-time value instead of a live read) — applied here to
   * the ordering between two different hooks in the same fiber rather than to a single async
   * closure.
   *
   * queryClient.isMutating() (a live, imperative read, taken fresh at the moment this effect body
   * runs) — not the reactive `isMutatingSignal` value below — is what actually decides whether to
   * flip isGuestState. `isMutatingSignal` (useIsMutating()) exists purely so this effect re-runs
   * every time the app-wide mutation count changes, giving it a fresh chance to re-check the live
   * value; using its own render-time value directly would reintroduce the identical stale-read
   * risk described above. Matches useCartMergeAndCap.ts's own documented reasoning for the same
   * hook pairing (queryClient.isMutating() for correctness, useIsMutating() for reactivity).
   * ---------------------------------------------------------------------------------------- */
  const { isRegistered } = useCustomerType();
  const [isGuestState, setIsGuestState] = useState(!isRegistered);
  const queryClient = useQueryClient();
  const isMutatingSignal = useIsMutating();
  const hasPendingPostAuthSettleRef = useRef(false);

  const handleAuthSuccess = useCallback(() => {
    hasPendingPostAuthSettleRef.current = true;
  }, []);

  const wishlistAuthDrawer = useWishlistAuthDrawer({
    onAuthSuccess: handleAuthSuccess,
    intentId: CART_WISHLIST_INTENT_ID,
  });

  useEffect(() => {
    if (!isRegistered) {
      setIsGuestState(true);
      return;
    }
    // Steady-state (a shopper already registered when this container mounts) never sets the ref,
    // so `!hasPendingPostAuthSettleRef.current` is true immediately — no artificial wait for
    // someone with nothing to wait for.
    if (!hasPendingPostAuthSettleRef.current || queryClient.isMutating() === 0) {
      hasPendingPostAuthSettleRef.current = false;
      setIsGuestState(false);
    }
  }, [isRegistered, isMutatingSignal, queryClient]);

  /**
   * Opens the one shared wishlist auth drawer from any row's guest click. ZimmCartItemActions'
   * onGuestWishlistClick is `() => void` — no event to forward, because every row shares this one
   * drawer instance (ZimmCartItemActions' own docblock explicitly rejects one useWishlistAuthDrawer
   * per row). useWishlistAuthDrawer's handleTriggerClick needs a SyntheticEvent purely to capture
   * `e.currentTarget` as the AC10 focus-return target.
   *
   * document.activeElement is deliberately NOT used as a substitute here, even though it could
   * plausibly hold the real clicked row's own link at this exact point in the call stack:
   * useWishlistAuthDrawer.ts's own handleTriggerClick comment already documents exactly why it
   * chose `e.currentTarget` over `document.activeElement` for this identical purpose — "unlike
   * document.activeElement which may still be body on click." Building this on a mechanism that
   * file's own author already rejected for the same job would trade one honest degradation for a
   * silently unreliable one.
   *
   * Corrected 2026-09-21 (step 4.6's own Tester, live-rendered rather than assumed): an earlier
   * version of this comment claimed the fallback lands on `document.body`, citing ZimmCartDrawer's
   * own doc for that behaviour. That doc describes what Chakra does with no `finalFocusRef` at
   * all — not what actually happens here, where `document.body` IS passed as `currentTarget`.
   * Live-rendering the real close sequence instead, focus actually lands on the still-open outer
   * cart drawer's own `aria-hidden` initial-focus sentinel (ZimmDrawer's own focus-management
   * internals) — a real, disclosed, named degradation, just a different actual mechanism than
   * previously claimed here: a keyboard user ends up parked on an invisible, unannounced element
   * rather than on `document.body`. Worth a follow-up ticket on the real UX gap; not fixed in this
   * step, which only owns getting this comment's own factual claim right. AC10 remains fully
   * correct for every genuine single-trigger caller (header/PDP wishlist icon), which still goes
   * through the unmodified <ZimmWishlistAuthDrawer/> wrapper, not this container.
   */
  const openGuestWishlistDrawer = useCallback(() => {
    wishlistAuthDrawer.handleTriggerClick({ currentTarget: document.body } as unknown as SyntheticEvent<HTMLElement>);
  }, [wishlistAuthDrawer.handleTriggerClick]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 3 — real remove/wishlist-move mutations, not stubs.
   * ---------------------------------------------------------------------------------------- */
  const removeItemFromBasketMutation = useShopperBasketsMutation('removeItemFromBasket');
  const customerId = useCustomerId();
  const { data: wishlist } = useWishList();
  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');

  const removeItem = async (itemId?: string): Promise<void> => {
    if (!basket?.basketId || !itemId) return;
    await removeItemFromBasketMutation.mutateAsync({ parameters: { basketId: basket.basketId, itemId } });
  };

  const moveToWishlist = async (productId: string): Promise<WishlistMoveResult> => {
    // Same lookup base product-detail/index.tsx's own handleAddToWishlist uses against
    // wishlist?.customerProductListItems.
    const isAlreadyInWishlist = wishlist?.customerProductListItems?.some(
      (item: { productId?: string }) => item.productId === productId,
    );
    if (isAlreadyInWishlist) {
      return { status: 'already-in-wishlist' };
    }
    if (!wishlist?.id) {
      // useWishList() auto-provisions a wish_list for a first-time registered customer and only
      // resolves it asynchronously (see that hook's own onSuccess) — surfaced as an error rather
      // than silently doing nothing, matching useCartMergeAndCap.ts's own "nothing valid to
      // address a write at" precedent.
      return { status: 'error', error: new Error('cartDrawerContainer: no wishlist available yet.') };
    }
    try {
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          // SDK param widening — useCustomerId returns string | null; onMoveToWishlist is only
          // ever invoked for a registered shopper (ZimmCartItemActions only calls this prop
          // directly when isGuest is false, and the resumed path only fires once isGuest has
          // become false — see usePendingWishlistItem.ts), matching product-detail/index.tsx's
          // own identical cast for the same real precondition.
          customerId: customerId as string,
        },
        body: {
          // NOTE: API does not respect quantity, it always adds 1 — see WISHLIST_ADD_QUANTITY's
          // own comment above.
          quantity: WISHLIST_ADD_QUANTITY,
          productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });
      return { status: 'success' };
    } catch (error) {
      return { status: 'error', error };
    }
  };

  return (
    <>
      <ZimmCartDrawer
        isOpen={isOpen}
        onClose={onClose}
        itemCount={itemCount}
        finalFocusRef={finalFocusRef}
        footer={<ZimmCartButtonGroup />}
      >
        {itemCount === 0 ? (
          <ZimmCartEmptyState />
        ) : (
          productItems.map((item) => {
            const fullProduct = item.productId ? productsById?.[item.productId] : undefined;
            const mergedProduct = {
              ...item,
              ...fullProduct,
              // Re-asserted after both spreads, matching base's own precedent exactly: the fetched
              // catalog Product record can carry its own `price` field, which would otherwise
              // silently overwrite the basket-line's real, discount-aware price.
              price: item.price,
              quantity: item.quantity,
              isProductUnavailable: !isProductsLoading ? !fullProduct : undefined,
            };
            // Pass criterion 1 — cartItemMapper's output used verbatim: productId/name feed
            // ZimmCartItemActions below (as productId/productName) — not a second, hand-rolled
            // mapping. The full mergedProduct object, not this mapped result, is what ProductItem
            // itself needs (see this file's own module docblock and cartItemMapper.ts's own
            // docblock for why its output alone is not a complete `product` prop).
            const mapped = selectCartItemProps(mergedProduct);
            return (
              <ProductItem
                key={item.itemId}
                product={mergedProduct}
                secondaryActions={
                  <ZimmCartItemActions
                    productId={mapped.productId ?? ''}
                    productName={mapped.name}
                    isGuest={isGuestState}
                    onRemove={() => removeItem(item.itemId)}
                    onMoveToWishlist={() => moveToWishlist(mapped.productId ?? '')}
                    onGuestWishlistClick={openGuestWishlistDrawer}
                  />
                }
              />
            );
          })
        )}
      </ZimmCartDrawer>
      <CartWishlistAuthGate wishlistAuthDrawer={wishlistAuthDrawer} />
    </>
  );
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Number of line items in the bag. Drives the header title only ("BAG • {itemCount}" vs
   *  "YOUR BAG IS EMPTY") — see `children`'s own doc below for the empty-vs-populated body. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items — or the empty-state body. This organism owns no item-rendering logic and
   *  no empty-vs-populated decision itself: it renders whatever `children` it is given,
   *  unconditionally, regardless of `itemCount`. The caller (`cartDrawerContainer.tsx`, SFCC-11
   *  plan step 4.6) decides between the real item list and `ZimmCartEmptyState`. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no message aggregation. Those remain separate,
 * later commits in this same plan — this organism is exercised only via its own Storybook
 * stories today. (Corrected 2026-09-21, SFCC-11 plan step 4.6: this paragraph used to also list
 * "no real empty-state body" here — no longer true. This component itself never owned that
 * decision; it renders whatever `children` it is given unconditionally. The real empty-state
 * body — deciding between the item list and `ZimmCartEmptyState` — is `cartDrawerContainer.tsx`'s
 * job, per `ZimmCartDrawerProps.children`'s own doc above.)
 *
 * Figma-fidelity audit fix, 2026-09-19: `ZimmDrawer`'s `title` was passed with no `titleStyle`,
 * so it silently took that prop's default (`'large'` → `heading1`, 24px) instead of the Figma
 * spec for this header ("BAG • #", 14px medium — `body2Strong`). Measured live before the fix:
 * 24px/400/32px against the 14px/500 spec. `ZimmDrawer` itself already supports both correctly
 * (`titleStyle="small"` → `body2Strong`, confirmed against `typography.ts`) — this was a missing
 * prop at the call site, not a defect in `ZimmDrawer`.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  return (
    <ZimmDrawer
      isOpen={isOpen}
      onClose={onClose}
      size="xLarge"
      title={title}
      titleStyle="small"
      finalFocusRef={finalFocusRef}
    >
      <chakra.div __css={styles.messages}>{messages}</chakra.div>
      {/* SFCC-11 plan step 4.6 fix: this used to be `itemCount === 0 ? <hardcoded placeholder> :
          children` — ignoring `children` entirely at zero items, no matter what the caller passed.
          Renders `children` unconditionally now; the empty-vs-populated decision belongs entirely
          to the caller (see ZimmCartDrawerProps.children's own doc above). */}
      <chakra.div __css={styles.body}>{children}</chakra.div>
      <chakra.div __css={styles.footer}>{footer}</chakra.div>
    </ZimmDrawer>
  );
};

