+  // hardcoded placeholder text before now, only on the (unrelated, unchanged) header title.
+  describe('body renders children unconditionally, regardless of itemCount (pass criterion 5 precondition)', () => {
+    test('renders children when itemCount is greater than 0', async () => {
+      render(
+        <ChakraProvider theme={theme}>
+          <ZimmCartDrawer isOpen={true} onClose={vi.fn()} itemCount={3}>
+            <p>Real line items</p>
+          </ZimmCartDrawer>
+        </ChakraProvider>,
+      );
+      expect(await screen.findByText('Real line items')).toBeInTheDocument();
+    });
+
+    // Mutation-tested: reverting to `itemCount === 0 ? <placeholder> : children` makes this fail —
