+    // would appear in its place instead.
+    test('renders children even when itemCount is 0 — no hardcoded placeholder takes its place', async () => {
+      render(
+        <ChakraProvider theme={theme}>
+          <ZimmCartDrawer isOpen={true} onClose={vi.fn()} itemCount={0}>
+            <p>Empty-state content</p>
+          </ZimmCartDrawer>
+        </ChakraProvider>,
+      );
+      expect(await screen.findByText('Empty-state content')).toBeInTheDocument();
+      expect(screen.queryByText('Your bag is empty.')).not.toBeInTheDocument();
+    });
+  });
+
   test('pressing Escape calls onClose', async () => {
     const onCloseSpy = vi.fn();
     await renderOpenCartDrawer(onCloseSpy);

