29	// (SVG imports resolve to raw path strings here, not components) — testing.md's documented known
30	// gap, same mock zimmCartDrawer/index.test.tsx's own suite already uses.
31	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
32	
33	const {
34	  mockUseCustomerId,
35	  mockUseCustomerType,
36	  mockUseProducts,
37	  mockRemoveItemFromBasket,
38	  mockCreateCustomerProductListItem,
39	  mockUseCustomerProductLists,
40	} = vi.hoisted(() => ({
41	  mockUseCustomerId: vi.fn(),
42	  mockUseCustomerType: vi.fn(),
43	  mockUseProducts: vi.fn(),
44	  mockRemoveItemFromBasket: vi.fn(),
45	  mockCreateCustomerProductListItem: vi.fn(),
46	  mockUseCustomerProductLists: vi.fn(),
