51	  return {
52	    ...actual,
53	    useCustomerId: mockUseCustomerId,
54	    useCustomerType: mockUseCustomerType,
55	    useProducts: mockUseProducts,
56	    useCustomerProductLists: mockUseCustomerProductLists,
57	    // useWishList (base hook, not mocked directly — this container calls it itself) calls
58	    // useCurrentCustomer() internally, which calls this. Not otherwise exercised by anything this
59	    // file asserts on — useWishList's own effective customerId still traces back to the mocked
60	    // useCustomerId() above, which is what this container's own moveToWishlist actually uses.
61	    useCustomer: () => ({ data: undefined, isLoading: false }),
62	    // useWishList's own createCustomerProductList (auto-provisioning) and this container's own
63	    // createCustomerProductListItem both come from this one hook, keyed by endpoint name — same
64	    // dispatch-by-name shape useShopperBasketsV2Mutation already needs below.
65	    useShopperCustomersMutation: (endpointName: string) => {
66	      if (endpointName === 'createCustomerProductListItem') {
67	        return { mutateAsync: mockCreateCustomerProductListItem };
68	      }
69	      // createCustomerProductList — useWishList's own internal auto-provision call. Never
70	      // asserted on directly in this file; a harmless stub is enough.
71	      return { mutate: vi.fn(), mutateAsync: vi.fn() };
72	    },
73	    useShopperBasketsV2Mutation: (endpointName: string) => {
74	      if (endpointName === 'removeItemFromBasket') {
75	        return { mutateAsync: mockRemoveItemFromBasket };
76	      }
77	      throw new Error(`Unexpected useShopperBasketsV2Mutation endpoint in this test: ${endpointName}`);
78	    },
79	  };
80	});
81	
82	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
83	  useCurrentBasket: () => ({ data: currentBasket, isLoading: false }),
84	}));
85	
86	vi.mock('@salesforce/retail-react-app/app/hooks/use-auth-modal', () => ({
87	  AuthModal: () => null,
88	}));
89	
