/**
 * SFCC-11 plan step 4.6 — cartDrawerContainer.tsx's own wiring contract. This step's own text
 * calls this the highest-risk piece in the plan ("a mistake here is exactly as invisible to any
 * single piece's own per-file review" as the earlier step 3.5 insertion was) — every dependency
 * this file wires together already has its own exhaustive test suite (ZimmCartDrawer,
 * cartItemMapper, useCartMergeAndCap, useCartMessages, ZimmCartItemActions, ZimmCartEmptyState,
 * ZimmCartButtonGroup, useWishlistAuthDrawer). Per testing.md's own scoping guidance, this file
 * mocks every one of those at its own smallest surface and asserts ONLY this container's own
 * contract: does it call each dependency with the right values, at the right time, and does it
 * make the right empty-vs-populated / guest-vs-registered decisions — not whether those
 * dependencies themselves behave correctly in isolation, which is already proven elsewhere.
 *
 * ZimmCartDrawer itself is the one dependency NOT mocked — it is small, already fully covered by
 * its own suite, and rendering it for real here is what actually proves pass criterion 5's second
 * half ("this container is what decides between the real item list and ZimmCartEmptyState"),
 * rather than merely a mocked component recording which children prop it was given.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import theme from 'app/theme';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { selectCartItemProps } from './cartItemMapper';
import { CartDrawerContainer } from './cartDrawerContainer';

